import{z as s,x as n,o as B,c as p,q as t,j as A,D as E,d as i,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"锡碎屑与防护","description":"","frontmatter":{"title":"锡碎屑与防护","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tin-debris.md","filePath":"litho/tin-debris.md","lastUpdated":1791063341000}'),d={name:"litho/tin-debris.md"};function h(D,a,m,P,C,c){const r=n("Mermaid");return B(),p("div",null,[a[2]||(a[2]=t('<h1 id="锡碎屑与防护" tabindex="-1">锡碎屑与防护 <a class="header-anchor" href="#锡碎屑与防护" aria-label="Permalink to &quot;锡碎屑与防护&quot;">​</a></h1><div class="epigraph"><p>每一次出光都伴随锡的离子、蒸汽和微滴；收集镜是第一面牺牲光学，防护必须在出光的同一微秒里完成。</p><footer>—— 改写自 ASML / Cymer 对 LPP debris 的公开分类与抑制叙述</footer></div><p><a href="/litho/tin-ionization">上一课</a>（锡电离态）。把靶做成准时到达的锡滴。缺口是：主脉冲把滴变成等离子体之后，质量并没有消失——高能离子、中性原子和微米/亚微米液滴继续飞向收集立体角。本课钉碎屑分类与防护层级。这面镜子本身是掠入射还是正入射、收多大立体角，留给<a href="/litho/collector-grazing">下一课</a>；多层收集镜如何退化成寿命账，是后面的<a href="/litho/collector-lifetime">收集镜寿命</a>一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/zeiss-euv-optics">收集镜</a>必须张在等离子体旁边，才能收数球面度的 13.5 nm。同一立体角也是碎屑的通道。离子溅射帽层与周期膜，中性锡镀成吸收层，高速微滴造成坑和粗糙——氢刻蚀对前两类薄膜有效，对后一类机械损伤帮助有限。只优化 <a href="/litho/euv-prepulse">CE</a> 而放任碎屑谱，IF 功率短期上升、镜子很快不可用。</p><p><span class="marginnote">术语翻译：debris（碎屑）就是打靶的「弹屑」。每一次把锡滴轰成等离子体，并不是所有锡都乖乖发光——没变成 EUV 的那部分锡，以高速离子、中性蒸汽和小液滴的形式四处飞溅，最终糊在收集镜上。管不住弹屑，灯再亮镜子也很快报废。</span></p><p>还要保护 IF 之后的扫描腔。<a href="/litho/euv-hydrogen-dgl">DGL</a> 用氢气流当无形窗，前提是光源舱已经把大部分质量流截住或化学成可抽气体。碎屑防护不是扫描机的事后过滤器，而是 LPP 源的一等设计量。</p><h3 id="三类碎屑不要写成一种「污染」" tabindex="-1">三类碎屑不要写成一种「污染」 <a class="header-anchor" href="#三类碎屑不要写成一种「污染」" aria-label="Permalink to &quot;三类碎屑不要写成一种「污染」&quot;">​</a></h3><p>公开叙述把 debris 分成：高速离子（动能溅射、植入）、中性蒸汽（均匀镀膜）、微滴（撞击、二次喷溅）。离子可用磁场偏转或气体碰撞减速；蒸汽靠氢自由基变成 SnH₄；微滴要靠靶形态（预脉冲）从源头减产，磁场对它几乎无效。把三类混成「开氢就干净」，会误判收集镜寿命。</p><p><span class="marginnote">碎屑质量流远大于带内光子质量当量。光源舱的第一任务是管理锡，第二才是出光。CE 数字不包含「有多少锡没变成 EUV 却打到了镜子上」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>量产公开架构是多层并行，而不是单点魔法。预脉冲把实心球改成盘，降低大微滴产额。相互作用点附近的缓冲氢缩短离子平均自由程。磁场把带电粒子弯出收集镜主区。收集镜自身浸在可原位刻锡的氢自由基里。朝 IF 的通道用 DGL 差压气帘，挡住扩散蒸汽。未电离锡走回收，避免在喷嘴和腔壁上再蒸发。</p><p>防护的光学代价写在功率账里：气体柱密度进入 \\(T_{\\mathrm{gas}}\\)，光阑与磁场结构可能挡一部分收集立体角。工程点是在挡屑与出光之间取窗，而不是把污染降到实验室本底。</p><h3 id="磁场与氢各管什么" tabindex="-1">磁场与氢各管什么 <a class="header-anchor" href="#磁场与氢各管什么" aria-label="Permalink to &quot;磁场与氢各管什么&quot;">​</a></h3><p>磁场只对带电粒子做功。中性微滴穿过磁场，必须靠源头与几何挡板。氢的双重角色——缓冲碰撞加化学反应——已在气锁课写过；本课只强调它清的是镀上的薄膜锡，补不回溅射坑。预脉冲偏心造成的侧向喷流，会打在收集镜特定方位，形成局部损伤热点，这是发生器稳定性与碎屑防护的耦合，不是气锁流量能单独拧平。</p><p><span class="marginnote">直觉类比：氢刻蚀像擦掉玻璃上的雾，离子溅射像砂纸磨出的划痕，微滴撞出的坑更像石头砸出的凹洞——雾能擦、划痕能抛，凹洞只能换玻璃。这就是为什么「多通氢气」救不了微滴损伤，必须在源头少产微滴。</span></p>',16)),(B(),A(o,null,{default:E(()=>[l(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLS%5B%22%E9%94%A1%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%22%5D%20--%3E%20ION%5B%22%E9%AB%98%E8%83%BD%E7%A6%BB%E5%AD%90%22%5D%0A%20%20PLS%20--%3E%20NEU%5B%22%E4%B8%AD%E6%80%A7%E8%92%B8%E6%B1%BD%22%5D%0A%20%20PLS%20--%3E%20DROP%5B%22%E5%BE%AE%E6%BB%B4%22%5D%0A%20%20ION%20--%3E%20B%5B%22%E7%A3%81%E5%9C%BA%E5%81%8F%E8%BD%AC%20%2F%20%E6%B0%94%E4%BD%93%E5%87%8F%E9%80%9F%22%5D%0A%20%20NEU%20--%3E%20H2%5B%22%E6%B0%A2%E8%87%AA%E7%94%B1%E5%9F%BA%E6%88%90%20SnH4%22%5D%0A%20%20DROP%20--%3E%20SRC%5B%22%E9%A2%84%E8%84%89%E5%86%B2%E5%87%8F%E4%BA%A7%20%2B%20%E6%8C%A1%E6%9D%BF%22%5D%0A%20%20B%20--%3E%20COL%5B%22%E6%94%B6%E9%9B%86%E9%95%9C%22%5D%0A%20%20H2%20--%3E%20COL%0A%20%20DROP%20--%3E%20COL%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"离子在鞘层和膨胀里被加速，打到多层膜时既溅射 Mo/Si，也把表面打毛，后续散射上升。蒸汽到达后若未被及时氢刻，吸收带内光，等效于 \\(R_{\\mathrm{col}}\\) 下降。微滴的动能密度高，局部熔化与二次抛射把损伤半径扩到比液滴本身大。三类过程的时间尺度不同：闪光是纳秒，膨胀是微秒，镀膜累积是小时到天——防护必须同时覆盖。",-1)),a[5]||(a[5]=e("p",null,"收集镜是椭球共轭：等离子体一个焦点，IF 另一个。碎屑沿直线或微弯轨迹走，不完全沿 EUV 射线。这才给磁场和挡板留下「挡屑少挡光」的几何缝。IF 合同面要求光谱与功率稳定；碎屑若漏到照明，投影镜的清洗窗口比收集镜窄得多，策略仍是「源侧牺牲、物镜侧严防」。",-1)),(B(),A(o,null,{default:E(()=>[l(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E7%BA%B3%E7%A7%92%E7%BA%A7%3A%20%E4%B8%BB%E8%84%89%E5%86%B2%E9%97%AA%E5%85%89%22%5D%20--%3E%20T2%5B%22%E5%BE%AE%E7%A7%92%E7%BA%A7%3A%20%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%E8%86%A8%E8%83%80%20%E7%A6%BB%E5%AD%90%E5%8A%A0%E9%80%9F%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E7%A6%BB%E5%AD%90%E6%92%9E%E5%A4%9A%E5%B1%82%E8%86%9C%20%E6%BA%85%E5%B0%84%E5%B9%B6%E6%89%93%E6%AF%9B%E8%A1%A8%E9%9D%A2%22%5D%0A%20%20T2%20--%3E%20T4%5B%22%E6%AF%AB%E7%A7%92%E5%88%B0%E7%A7%92%E7%BA%A7%3A%20%E8%92%B8%E6%B1%BD%E5%88%B0%E8%BE%BE%E6%9C%AA%E5%88%BB%E5%8C%BA%22%5D%0A%20%20T4%20--%3E%20T5%5B%22%E9%95%80%E6%88%90%E5%90%B8%E6%94%B6%E8%86%9C%20R%20%E7%BC%93%E9%99%8D%22%5D%0A%20%20T6%5B%22%E7%9E%AC%E9%97%B4%3A%20%E5%BE%AE%E6%BB%B4%E7%86%94%E5%9D%91%E5%B9%B6%E4%BA%8C%E6%AC%A1%E6%8A%9B%E5%B0%84%22%5D%20--%3E%20T7%5B%22%E6%9C%BA%E6%A2%B0%E5%9D%91%20%E6%B0%A2%E5%88%BB%E6%97%A0%E6%95%88%22%5D%0A%20%20T3%20--%3E%20S%5B%22%E4%B8%89%E7%B1%BB%E6%97%B6%E9%97%B4%E5%B0%BA%E5%BA%A6%E4%B8%8D%E5%90%8C%20%E9%98%B2%E6%8A%A4%E5%BF%85%E9%A1%BB%E5%88%86%E5%B1%82%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20T5%20--%3E%20S%0A%20%20T7%20--%3E%20S%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：初学者容易以为「磁场一开，碎屑全挡住」。磁场只对带电粒子施加力，中性蒸汽和微滴毫无反应地直线穿过；挡它们得靠氢化学和几何挡板。三层防护各管一类，缺任何一层，收集镜寿命都按最短的那块木板算。</span></p><p><span class="marginnote">不要把 DPP 电极喷溅和 LPP 锡滴碎屑写成同一种源。量产 NXE 公开叙述是锡滴 LPP；电极金属碎屑是另一条已退出 HVM 主线的问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出未公开的磁场特斯拉数、氢 SCCM 或挡板图纸。也不把某次会议的「无碎屑 LPP」海报写成厂内状态。后课默认：说到收集镜退化，先问离子溅射、蒸汽镀膜还是微滴坑，三类对策不同。</p><p>换靶材（氙、锂）在历史上正是为了碎屑，但带内 CE 或重复频率不够，量产仍停在锡。追求极端 CE 若以微滴暴增为代价，工厂综合成本可能变差。引用以 ASML/Cymer debris 公开分类为准，等离子体细节见 Bakshi。</p><p><span class="marginnote">氢化物抽走是化学通道，不是「锡消失了」。排气处理、毒性与泵的耐锡能力属于工厂设施，光学课可以不展开规范，但不能暗示碎屑只存在于镜子表面。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LPP 碎屑分离子、中性蒸汽、微滴，对策分别是磁场/缓冲、氢刻蚀、源头减产。</li><li>收集镜与碎屑共享立体角，防护是出光设计的一部分。</li><li>氢清薄膜锡，清不掉高速微滴的机械坑。</li><li>DGL 挡的是漏向扫描腔的质量流，不能替代源侧谱控制。</li><li>收集镜的几何与有效收集下一课；这些损伤随后写成反射率与寿命。</li><li>出处：ASML / Cymer LPP debris 公开材料；Bakshi, <em>EUV Lithography</em>。</li></ul>',8))])}const T=s(d,[["render",h]]);export{f as __pageData,T as default};
